#include <bits/stdc++.h>
#define LL long long
#define U unsigned
#define INF 9223372036854775807LL
#define MINF (-9223372036854775808LL)
bool isPrimeNumber(LL x){
    if(x<2) return false;
    for(LL i=2; i<=sqrt(x); i++){
        if(x%i==0) return false;
    }
    return true;
}
inline LL readLongLong(){
    LL x=0,f=1; char ch=getchar();
    while (!isdigit(ch)){ if (ch=='-') f=-1; ch=getchar(); }
    while (isdigit(ch)){ x=x*10+ch-48; ch=getchar(); }
    return x*f;
}
LL computeGCD(LL a, LL b){
    return b==0 ? a : computeGCD(b, a%b);
}
LL modPow(LL base, LL exp, LL mod){
    LL res=1;
    for(; exp; exp>>=1){
        if(exp&1) res=res*base%mod;
        base=base*base%mod;
    }
    return res;
}
using namespace std;
/* Additional code omitted for brevity, same as original */
#define MOD_A 998244353LL
#define MOD_B 1000000007LL
LL totalN;
LL totalCount;
LL prefixSumArr[7];
std::vector<LL> prefixDigitsArr[7];

void generateNumbers(LL depth, LL current){
    if(depth>6) return;
    prefixDigitsArr[depth].push_back((totalCount - current + MOD_A)%MOD_A);
    prefixSumArr[depth]+=(totalCount - current + MOD_A)%MOD_A;
    totalCount++;
    for(LL d=0; d<=9; d++){
        generateNumbers(depth+1, current*10+d);
    }
}

LL counter2=-1, finalAns;
void processNumbers(LL depth, LL current){
    if(current>N) return;
    if(current*1000000+999999<=N && current*10000000>N){
        for(LL i=0; i<=6; i++){
            LL shift=(counter2+1 - current*modPow(10,i,MOD_A)%MOD_A + MOD_A)%MOD_A;
            LL pos=lower_bound(prefixDigitsArr[i].begin(), prefixDigitsArr[i].end(), MOD_A-shift) - prefixDigitsArr[i].begin();
            finalAns += (prefixSumArr[i] + shift*prefixDigitsArr[i].size() - MOD_A*(prefixDigitsArr[i].size()-pos));
            finalAns %= MOD_B;
        }
        counter2+=totalCount;
        return;
    }
    counter2++;
    finalAns += ((counter2 - current)%MOD_A + MOD_A)%MOD_A;
    finalAns %= MOD_B;
    for(LL d=0; d<=9; d++){
        if(!depth && d==0) continue;
        processNumbers(depth+1, current*10+d);
    }
}

int main(){
    totalN=readLongLong();
    generateNumbers(0,0);
    for(LL i=0; i<=6; i++) sort(prefixDigitsArr[i].begin(), prefixDigitsArr[i].end());
    processNumbers(0,0);
    std::cout<<finalAns;
    return 0;
}
